package com.example.cookoffline.ui
import android.app.Application; import androidx.lifecycle.*; import com.example.cookoffline.data.*; import kotlinx.coroutines.flow.*; import kotlinx.coroutines.launch
data class UiState(val loading: Boolean = false, val recipes: List<RecipeEntity> = emptyList(), val ingredients: List<IngredientEntity> = emptyList(), val message: String = "")
class MainViewModel(app: Application) : AndroidViewModel(app) { private val repo = Repository(AppDatabase.get(app)); private val _s = MutableStateFlow(UiState()); val state: StateFlow<UiState> = _s; init { viewModelScope.launch { repo.seedIfEmpty(); refresh() } }; fun refresh() = viewModelScope.launch { _s.update { it.copy(loading = true) }; val r = repo.availableRecipes(); val i = repo.allIngredients(); _s.update { it.copy(loading = false, recipes = r, ingredients = i) } }; fun plan(id: Long) = viewModelScope.launch { runCatching { repo.planMeal(id, 2) }.onSuccess { _s.update { it.copy(message = "成功") } }.onFailure { e - { it.copy(message = e.message ?: "失败") } }; refresh() } }
